/** The caller workflow `init` writes: the maintained template with two anchors replaced (contract section 5.5). Pure. */

const OPERATOR_ANCHOR = "operator: EDIT-THIS-github-login";
const PIN_ANCHOR = /(\/review\.yml@)[^\s#]+/g;

const count = (text: string, pattern: RegExp) => (text.match(pattern) ?? []).length;

/** The one line comment that opens a generated file. */
export function callerHeader(p: { version: string; now: string }) {
  return `# Generated by wachiman init ${p.version} on ${p.now.slice(0, 10)}; Actions is billed through the ANTHROPIC_API_KEY secret; local runs use your signed-in claude.`;
}

/**
 * Replaces `operator: EDIT-THIS-github-login` with the login, double-quoted so YAML never reads a
 * login such as `null`, `true` or `123` as another type (the login regex allows no quote), and the tag after `review.yml@` with
 * `tag`; nothing else in the template changes, so its comments and triggers ship as written. With a
 * `header`, that comment line goes first. Throws when either anchor is not found exactly once: the
 * template and this renderer are tested together.
 */
export function renderCallerWorkflow(template: string, p: { operator: string; tag: string; header?: string }) {
  if (template.split(OPERATOR_ANCHOR).length - 1 !== 1) {
    throw new Error(`the caller template must contain "${OPERATOR_ANCHOR}" exactly once; init and templates/wachiman-review-caller.yml are out of step.`);
  }
  if (count(template, new RegExp(PIN_ANCHOR.source, "g")) !== 1) {
    throw new Error("the caller template must pin the reusable workflow once, as `…/review.yml@<tag>`; init and templates/wachiman-review-caller.yml are out of step.");
  }
  const body = template
    .replace(OPERATOR_ANCHOR, () => `operator: "${p.operator}"`)
    .replace(PIN_ANCHOR, (_match, prefix: string) => `${prefix}${p.tag}`);
  return p.header === undefined ? body : `${p.header}\n${body}`;
}
